def unique_digits(x):
    """Return sorted list of all elements from the list x which don't contain any even digits."""
    result = []

    for num in x:
        str_num = str(num)

        # Check if all digits in the number are odd
        all_even = True
        for digit in str_num:
            if int(digit) % 2 == 0:
                all_even = False
                break

        if all_even:
            # If all digits were odd, add it to result list
            result.append(num)

    result.sort()

    return result

