def is_prime(n):
    """Return true if a given number n is prime, and false otherwise."""
    # Check for numbers less than 2 which are not prime
    if n < 2:
        return False
    # Check for even numbers greater than 2 which are not prime except 2 itself
    elif n == 2:
        return True
    # Check for odd numbers greater than 2
    else:
        # Loop through all possible divisors from 3 up to but not including sqrt(n)
        for i in range(3, int(n**0.5) + 1, 2):
            # If n is divisible by any of these divisors, it's not prime
            if n % i == 0:
                return False
        return True

