def circular_shift(x: int, shift: int) -> str:
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    str_x = list(str(x))
    len_x = len(str_x)
    shifted_x = []

    for i in range(-shift, 0, 1):
        shifted_x.append(int(str_x[i]))

    for i in range(len_x):
        shifted_x.append(int(str_x[i]))

    shifted_x = shifted_x[-len_x:]
    result = ''.join(map(str, shifted_x))

    if len_x <= shift or (shift < 0 and len_x >= shift % len_x):
        return str(result).lstrip('0')
    else:
        return str(result).rjust((shift - 1) % len_x).lstrip('0')

