def prime_fib(n: int) -> int:
    """Returns the nth prime Fibonacci number."""
    fib_counter, prime_count = 0, 0
    current_fib = 0

    while True:
        current_fib += 1
        fib_value = fibonacci(current_fib)

        if is_prime(fib_value) and (prime_count + 1 >= n):
            break

        prime_count += 1

    return fib_value

