def max_sum(arr):
    length = len(arr)
    dp_increasing = [0] * (length)
    dp_decreasing = [0] * (length)
    result = 0

    for i in range(length):
        current_max = 0

        # Calculate increasing subsequences ending at arr[i]
        for j in range(i + 1):
            if arr[i] > arr[j]:
                current_max = max(current_max, dp_increasing[j])

        dp_increasing[i] = 1 + current_max

    for i in range(length - 1, -1, -1):
        current_max = 0

        # Calculate decreasing subsequences starting at arr[i]
        for j in range(i, length):
            if arr[i] > arr[j]:
                current_max = max(current_max, dp_decreasing[j])

        dp_decreasing[i] = 1 + current_max

    for i in range(length):
        result = max(result, dp_increasing[i] + dp_decreasing[i] - 1)

    return result

