def find_first_occurrence(arr, target):
    l, r = 0, len(arr)-1
    result = None
    while l <= r:
        mid = l + (r-l)//2
        if arr[mid] > target:
            r -= 1
        elif arr[mid] < target:
            l += 1
        else:
            # If arr[mid] equals target
            # Check if this is the first occurrence or if the current element is not the first one
            # If not, move left pointer to avoid counting duplicate occurrences on both sides.
            while l <= mid-1 and arr[l] == arr[mid]:
                l += 1
            # Update result to be the current position if found.
            result = mid
            break

    return result if result is not None else -1

