def largest_subset(nums):
    nums.sort(reverse=True) # Sort in reverse to easily pick larger numbers
    dp = [0] * len(nums)
    for i in range(len(nums)):
        max_val = 0
        for j in range(i + 1):
            if nums[j] % nums[i] == 0: # Check if the current element can form a larger subset with previous elements
                max_val = max(max_val, dp[j])
        dp[i] = max_val + 1
    return max(dp) # The result is the length of the longest subset

