def shell_sort(arr):
    length = len(arr)
    gap = int(length / 2)

    while (gap > 0):

        for i in range(gap, length):

            temp = arr[i]

            j = i

            while (j >= gap) and (arr[j - gap] > temp):
                arr[j] = arr[j - gap]
                j = j - gap

            arr[j] = temp

        gap //= 2

    return arr

