def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    sorted = False

    while sorted is False:
        gap //= shrink_factor
        if gap <= 1:
            sorted = True

        for i in range(gap, len(arr)):
            temp = arr[i]
            j = i - gap

            while (j >= 0) and (arr[j] > temp):
                arr[j + gap], arr[j] = arr[j], temp
                j -= gap

    return arr

