def bell_number(n):
    """Return the nth Bell number."""
    if n == 0: return [0]
    result = [0] * (n + 1)
    result[0], result[1] = 1, 1
    for i in range(2, n + 1):
        result[i] = 0
        for j in range(i + 1):
            result[i] += result[j - 1] * binomial(i, j)
    return result[n]
def binomial(n, k):
    """Return the binomial coefficient C(n, k) (n choose k)."""
    if k > n - k: k = n - k
    result = 1
    for i in range(k):
        result = int(result * (n - i))
    for i in range(i + 1):
        result = int(result / (i + 1))
    return result

