def count_divisors(num):
    """Check if the number has an even number of divisors"""

    divisor_count = 0

    for i in range(1, int(num**0.5)+1):
        if (num % i) == 0: # Check if 'i' is a divisor
            # If 'i' is not the square root, it's counted as two distinct divisors
            # If 'i' is the square root, it's only counted as one
            if i*i != num:
                divisor_count += 2
            else:
                divisor_count += 1

    return divisor_count

