def catalan_number(n: int) -> int:
    """Returns the nth Catalan number."""
    catalan_numbers = [0] * (n + 1)
    catalan_numbers[0], catalan_numbers[1] = 1, 1

    for i in range(2, n + 1):
        catalan_numbers[i] = 0
        for j in range(i):
