    return round(total_years)

def cal_sum(n: int) -> int:
    """Return sum of first n pell numbers."""
    if n < 1:
        return 0

    # Initialize first two Perrin numbers
    Perrin_0, Perrin_1 = 3, 4

    for _ in range(2, n):
        next_number = Perrin_0 + Perrin_1
        Perrin_0, Perrin_1 = Perrin_1, next_number

    return Perrin_1

